python3 -c "
import json, os, sys
d = json.load(sys.stdin)
agent = d.get('agent_type')
path = os.path.abspath((d.get('tool_input') or {}).get('file_path') or '.')
for root in (d.get('cwd'), os.environ.get('CLAUDE_PROJECT_DIR')):
    if not root:
        continue
    try:
        rel = os.path.relpath(path, root).replace(os.sep, '/')
        top = rel.split('/')[0]
    except ValueError:
        continue
    if rel == '.claude/state' or rel.startswith('.claude/state/'):
        print('[harness] Bloqueado: .claude/state/ lo escriben solo los scripts del harness.', file=sys.stderr)
        sys.exit(2)
    if top not in ('src', 'tests') or agent == 'implementer':
        continue
    if agent == 'adversary' and top == 'tests':
        continue
    if agent == 'adversary':
        print('[harness] Bloqueado: el adversary solo escribe tests (tests/). No toca el código de producto: el arreglo es de quien implementa.', file=sys.stderr)
        sys.exit(2)
    main = agent in (None, 'leader')
    try:
        feats = json.load(open(os.path.join(root, 'feature_list.json'), encoding='utf-8'))['features']
    except Exception:
        feats = []
    if main and any(f.get('status') == 'in_progress' and f.get('size') == 'small' for f in feats):
        continue
    if main:
        print('[harness] Bloqueado: la sesión principal solo escribe en src/ y tests/ mientras hay una feature small en in_progress (plan aprobado por el humano). Si es trivial, medium o large, delega el cambio en el implementer con la herramienta Agent.', file=sys.stderr)
    else:
        print('[harness] Bloqueado: en src/ y tests/ solo escriben el implementer, el adversary (solo en tests/) y, en una feature small, la sesión principal (agente actual: ' + agent + ').', file=sys.stderr)
    sys.exit(2)
"

python3 -c "import json, os, re, subprocess, sys
try:
    d = json.load(sys.stdin)
except Exception:
    d = {}
roots = [r for r in (os.environ.get('CLAUDE_PROJECT_DIR'), d.get('cwd')) if r and os.path.isfile(os.path.join(r, 'init.sh'))]
if not roots:
    sys.exit(0)
try:
    run = subprocess.run(['bash', 'init.sh', '--status'], cwd=roots[0], capture_output=True, text=True, timeout=40)
except Exception as e:
    print('[harness] No se pudo generar el estado del proyecto: ' + str(e))
    sys.exit(0)
lines = re.sub(chr(27) + r'\\[[0-9;]*m', '', run.stdout).splitlines()
start = next((i for i, l in enumerate(lines) if 'Estado del trabajo' in l), len(lines))
problems = [l for l in lines[:start] if '[FAIL]' in l or '[WARN]' in l]
print('== Estado real del proyecto (generado por ./init.sh --status al iniciar la sesión) ==')
print('Manda sobre cualquier estado escrito a mano en progress/. No incluye análisis estático ni tests: para eso ejecuta ./init.sh.')
print(chr(10).join(l for l in problems + lines[start:] if l.strip()))
sys.exit(0)"
